package za.ac.cput.domain; import jakarta.persistence.*;
@Entity public class HomeAddress { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long addressId; private String streetNumber,houseNumber,city,province,postalCode,country; protected HomeAddress(){} private HomeAddress(Builder b){streetNumber=b.streetNumber;houseNumber=b.houseNumber;city=b.city;province=b.province;postalCode=b.postalCode;country=b.country;} public Long getAddressId(){return addressId;} public String getStreetNumber(){return streetNumber;} public String getHouseNumber(){return houseNumber;} public String getCity(){return city;} public String getProvince(){return province;} public String getPostalCode(){return postalCode;} public String getCountry(){return country;} public static class Builder{private String streetNumber,houseNumber,city,province,postalCode,country; public Builder setStreetNumber(String v){streetNumber=v;return this;} public Builder setHouseNumber(String v){houseNumber=v;return this;} public Builder setCity(String v){city=v;return this;} public Builder setProvince(String v){province=v;return this;} public Builder setPostalCode(String v){postalCode=v;return this;} public Builder setCountry(String v){country=v;return this;} public Builder copy(HomeAddress a){streetNumber=a.streetNumber;houseNumber=a.houseNumber;city=a.city;province=a.province;postalCode=a.postalCode;country=a.country;return this;} public HomeAddress build(){return new HomeAddress(this);} } }